#include <string.h>

char *decrypt(const char *s) {
    int slen = (int)strlen(s);
    int cap = 16, count = 0;
    int *crypt = malloc(cap * sizeof(int));
    int ngroups = 1;
    int start = 0, gi = 0;
    for (int p = 0; p < slen; p++) {
        if (s[p] == '#') ngroups++;
    }
    for (int p = 0; p <= slen; p++) {
        if (p == slen || s[p] == '#') {
            int len = p - start;
            if (!(p == slen && len == 0)) {
                int j = 0;
                if ((gi == ngroups - 1) && (slen == 0 || s[slen - 1] != '#')) j = len;
                if (len > 2) j = len - 2;
                for (int k = 0; k < j; k++) {
                    if (count == cap) {
                        cap *= 2;
                        crypt = realloc(crypt, cap * sizeof(int));
                    }
                    crypt[count++] = s[start + k] - '0';
                }
                if (j < len) {
                    char tail[8];
                    int tl = len - j;
                    if (count == cap) {
                        cap *= 2;
                        crypt = realloc(crypt, cap * sizeof(int));
                    }
                    memcpy(tail, s + start + j, tl);
                    tail[tl] = '\0';
                    crypt[count++] = atoi(tail);
                }
            }
            gi++;
            start = p + 1;
        }
    }
    char *result = malloc(count + 1);
    for (int m = 0; m < count; m++) {
        result[m] = (char)(('a' + crypt[m]) - 1);
    }
    result[count] = '\0';
    free(crypt);
    return result;
}

