int *zero_front(const int *nums, int n) {
    if (nums == NULL) {
        return NULL;
    }
    int *result = malloc(n * sizeof(int));
    int zeroes_pos = 0;
    int others_pos = n - 1;
    for (int i = 0; i < n; ++i) {
        if (nums[i] == 0) {
            result[zeroes_pos] = 0;
            ++zeroes_pos;
        } else {
            result[others_pos] = nums[i];
            --others_pos;
        }
    }
    return result;
}

